questionvariables.text:
stack_include("https://raw.githubusercontent.com/STACK-for-Chemistry/STACK-for-Chemistry/refs/heads/main/Modules/Utilized/pse.mac");
stack_include("https://raw.githubusercontent.com/STACK-for-Chemistry/STACK-for-Chemistry/refs/heads/main/Modules/Utilized/electrochemistry.mac");
stack_unit_si_declare(true);

/* Select a reduction of the form M^n+ + n e^- -> M from the electrochemistry module. */
metal_pair: rand(chem_electrochem_metal_pairs_array());
metal_ion: first(metal_pair);
metal: second(metal_pair);
n_electrons: third(metal_pair);
molar_mass: chem_data(metal, "AtomicMass");
metal_name: chem_data(metal, "Name");

/* [anion formula, anion charge, German salt-name suffix]. */
anions: [["Cl", 1, "chlorid"], ["O", 2, "oxid"], ["S", 2, "sulfid"], ["Br", 1, "bromid"], ["F", 1, "fluorid"], ["I", 1, "iodid"]];
anion: rand(anions);
anion_symbol: first(anion);
anion_charge: second(anion);
anion_suffix: third(anion);

/* Form the lowest whole-number-ratio salt formula, e.g. ZnCl2 and Zinkchlorid. */
salt_gcd: gcd(n_electrons, anion_charge);
metal_coefficient: anion_charge/salt_gcd;
anion_coefficient: n_electrons/salt_gcd;
formula_count(x) := if is(x = 1) then "" else string(x);
salt_formula: sconcat(metal, formula_count(metal_coefficient), anion_symbol, formula_count(anion_coefficient));
salt_name: sconcat(metal_name, anion_suffix);
salt_display: chem_display(salt_formula);

/* Current and electrolysis time are varied independently. */
current: rand([1, 2, 3, 4, 5]);
duration_min: rand([5, 10, 15, 20, 25, 30]);
duration_s: 60*duration_min;
F: 96485;
charge: current*duration_s;
mass_deposited: float(round(1000*molar_mass*charge/(n_electrons*F))/1000);
ta_mass: stackunits(mass_deposited, g);

metal_ion_display: chem_display(metal_ion);
half_equation: chem_display(sconcat(metal_ion, "(aq) + ", string(n_electrons), "e^- -> ", metal, "(s)"));
